css:
/* Flat style: no drop shadows anywhere, but keep keyboard focus rings visible. */
*:not(:focus-visible), *::before, *::after {
  box-shadow: none !important;
}

/* Composer: the outer card disappears; only the text field is a box. */
[data-chat-composer-form] {
  --app-theme-surface-raised: transparent;
  --chat-composer-glass-surface: transparent;
  --chat-composer-outline: transparent;
}
[data-slot="composer-host"],
[data-slot="composer-host"]::before,
[data-slot="composer-host"]::after {
  background: transparent !important;
  border-color: transparent !important;
  backdrop-filter: none !important;
}
[data-composer-prompt-surface="true"] {
  background: #141414 !important;
  border: 1px solid #2a2a2a !important;
  border-radius: 16px !important;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.6) !important;
}
